from itertools import product

# Generate all possible binary sequences of length 17
sequences = list(product([-1, 1], repeat=17))

# Filter sequences based on the given constraints
valid_sequences = []
for seq in sequences:
    if seq[1] == -1 and seq[6] == 1 and seq[9] == -1:
        c = [0] * 17
        for k in range(1, 17):
            for i in range(17 - k):
                c[k] += seq[i] * seq[i + k]
        if c[7] == 3 and c[8] == -2 and c[12] == 0:
            valid_sequences.append(seq)

# Check if any valid sequence has low aperiodic autocorrelation
solutions = []
for seq in valid_sequences:
    c = [0] * 17
    for k in range(1, 17):
        for i in range(17 - k):
            c[k] += seq[i] * seq[i + k]
    if sum([x**2 for x in c[1:]]) <= 40:
        solutions.append(seq)

# Print the solution or state UNSATISFIABLE
if solutions:
    print(solutions[0])
else:
    print("UNSATISFIABLE")
